function world = emptyWorld(arenaSize, ceiling, wallHeight)
%EMPTYWORLD  World struct without obstacles.
%   pillars: N x 4 [x y radius height]; movers: positions M x 3, velocities M x 3.
world = struct( ...
    "size", arenaSize, ...
    "ceiling", ceiling, ...
    "wallHeight", wallHeight, ...
    "pillars", zeros(0, 4), ...
    "pillarAlbedo", zeros(0, 1), ...
    "moverPos", zeros(0, 3), ...
    "moverVel", zeros(0, 3), ...
    "moverRadius", zeros(0, 1), ...
    "moverAlbedo", zeros(0, 1));
end
